import {POWERUPS,selectedPower,choosePower,canChoosePower} from '../data/powerups.js';
import {characterById} from '../data/characters.js';
import {appearance} from '../data/appearance.js';
export function powerupMarkup(app){
 const editable=canChoosePower(app);
 return `<div class="powerup-intro"><span class="eyebrow">IL BANCO DELLA BANDA · TUTTI GLI 11</span><h3>UN PERSONAGGIO.<br>IL TUO STILE.</h3><p>Scegli fra lo speciale classico e due varianti per ogni personaggio. Premi sempre <b>B / K</b> in missione: nessun tasto aggiuntivo.</p><p class="powerup-context">${editable?'Le scelte sono gratuite e restano salvate su questo dispositivo.':'Sei in missione: le varianti si cambiano dalla home o dal covo.'}</p></div><div class="powerup-grid">${Object.entries(POWERUPS).map(([id,options])=>{
  const person=characterById(id),a=appearance(id),selected=selectedPower(app.settings,id).id;
  return `<fieldset class="powerup-card" style="--power-color:${person.color}"><legend>${person.name==='Click'?'Klaudio / Click':person.name}</legend><div class="powerup-person"><div class="powerup-portrait" aria-hidden="true"><i style="background-image:url(assets/${a.texture}-atlas.png);background-size:400% ${a.rows*100}%;background-position:0 ${a.row/(a.rows-1)*100}%"></i></div><div><small>${person.role}</small><b>${person.special}</b></div></div>${options.map(p=>`<label class="powerup-option ${p.id===selected?'selected':''}"><input type="radio" name="power-${id}" value="${p.id}" data-power-person="${id}" ${p.id===selected?'checked':''} ${editable?'':'disabled'}><span><b>${p.name}</b><small>${p.description}</small></span></label>`).join('')}</fieldset>`;
 }).join('')}</div><p class="notice">Una variante per personaggio. Nel prologo i bambini mantengono lo scatto. I boss resistono alle proiezioni e agli stordimenti prolungati. Paula marca i nemici: passa a Nico entro 6 secondi per la Chiusura del cerchio.</p><p id="powerup-feedback" role="status" aria-live="polite"></p>`;
}
export function renderPowerups(app,content){content.innerHTML=powerupMarkup(app);content.querySelectorAll('[data-power-person]').forEach(input=>input.onchange=()=>{const id=input.dataset.powerPerson;if(!choosePower(app,id,input.value))return;renderPowerups(app,content);content.querySelector(`[data-power-person="${id}"][value="${input.value}"]`)?.focus({preventScroll:true});content.querySelector('#powerup-feedback').textContent=`${characterById(id).name}: ${selectedPower(app.settings,id).name} equipaggiato.`;});}
